        "在这样的背景下，我认为“生存——发展—— 自我实现“这种传统三段论式的职业生涯会被“万花筒生涯” 取代。",
        "这个理论最早由学者丽莎· 梅尼埃洛( Lisa Mainiero ) 和雪莉· 沙利文( Sh.erry Sullivan ) 提出。",
