      "author": "和渊",
      "summary": "我的一位朋友最近很焦虑。她的儿子小A读初二，每天作业本上的答案工整漂亮，平常作文练习也写得\n“逻辑严密、论证充分\n” ,\n可期中考试成绩出来，她傻眼了数学从85分掉到了62分，作文\n“离题万里\n”\n。后来她才知道，小A每天偷偷用AI，数学题拍照秒出答案，作文直接让AI生成框架。看起来每天晚上在家很努力，实际上大脑一直没有学进去新东西。而我的一个学生小B同样在用AI学习，结果却完全不同。",
