        "我们生活的这个世界，已经在不知不觉中被打造成了最适合人类生活的样子。",
        "要让机器人真正走进人类社会，与我们协同工作，它们中的绝大多数就要以“人的样子” ,在“ 为人设计” 的环境中行动。",
        "第二场是要不要冠以“世界” 之名。",
        "这个顾虑更实际：",
        "我们能不能请到足够多的国际队伍？",
        "真请来了，我们自己的队伍会不会被比下去？",
        "但很快，大家达成了共识既然要办，就要让它成为一场真正的国际赛事，而不只是“自我欣赏＂的展示。",
        "402当机器人迎来它的奥运时刻我们最终邀请了来自世界各地的280支参赛队伍。",
        "其中足球项目与已有二十多年历史的RoboCup1合作，吸引了十余支海外队伍参赛，成为本届运动会中最为国际化的——项。",
        "值得一提的是，足球赛事采用中国企业加速进化公司的Tl型号机器人作为通用平台。",
        "这既考验了国产人形机器人的技术成熟度，也让中国制造在国际赛场上以统—标准接受检验。",
        "机器人参与的足球比赛现场:.:· 重新定义运动会你大概已经猜到了当参赛选手变成人形机器人以后，这场运动会就不可能按照人类设计的剧本四平八稳地推进。",
        "唱1 . 机器人世界杯，创办千1997年，是全球最具影响力的机器人竞赛之一，旨在通过足球比赛推动机器人技术发展。",
        "在此之前，RoboCup使用的是Aldebaran公司的NAO机器人。",
        ":我们的运动员，有很多每隔一小时就要充电。",
