        "前面举的只是几个小例子，但你也许已经看出来了虽然”运动会” 这个框架我们都很熟悉，可一旦主角变成机器人，几平每——处细节都要重新定义。",
        "所以接下来，我想带你从幕后看——看，我们是怎么反复推敲、调整那些看似细微的环节，让整场活动顺利落地的。",
        "比如，运动员宣誓。",
        "按照奥运会惯例，宣誓词是“ 为了体育的光荣和团队的荣誉. . . . . . 尊重并遵守运动会各项比赛规则＂。",
        "但机器人要怎么宣誓？",
        "如果照搬这段话，总觉得有点别扭。",
