        "最后定下了这——版：",
        "“谨以全体机器人运动员名义庄严宣誓，尊重对手、尊重裁判、尊重规则，承人类之智，展科技之力。",
        "＂既保留了仪式感，又让机器人有了属于自己的表达。",
        "再比如，开幕式的方阵入场。",
        "人类运动会总少不了声势浩大的运动员方阵，但我们起初并没有打算让机器人列队保持队形同时前进，对控制系统和通信稳定性都是巨大的挑战，而任何一个机器人404当机器人迎来它的奥运时刻摔倒，都可能带倒一整排。",
        "所以，就算只是个5 x 5的小方阵，各家企业负责人也都捏着一把汗谁都不想让自家机器人在开幕式上倒下。",
        "最终，加速进化公司接下了任务，连夜调机、补电、测试。",
        "好在开幕式当天一切顺利，25个机器人整齐入场，动作干净利落。",
        "台下的观众可能没有意识到，看起来再普通不过的“ 走方阵＂，其实是我们全程最担心的一个环节。",
        "还比如，比赛跑道的设计。",
        "我们一开始沿用了国际田联标准的八条跑道。",
        "可讨论到一半，突然有人提出：",
        "“ 既然参赛的是机器人，为什么还要完全照搬人类的标准设计？",
        "” 那——刻我们意识到，这场运动会真正要做的，是帮机器人建立自己的比赛规则。",
        "所以，跑道从八条调整为四条，每条宽2.44米，给运动员们留出了更多的安全距离和容错空间。",
