        "有人强调现场的视觉效果，有人更在意转播画面的观感。",
        "最后我们统一了方向既然主角机器人运动员在跑道起点等待发令405是机器人，就该从它们的视角出发，选择深蓝色跑道配臼色边线。",
        "这种强对比色对机器的视觉系统最友好，它们识别更精准，也能避免因为“看不清边线” 而被罚。",
        "最后一个例子涉及一项更复杂的规则设计。",
        "赛跑项目中，操控机器人和自主机器人是同场竞技的，前者需要人类操控员在场边并跑，实时发出控制指令；",
        "后者则完全依靠自身的感知与算法独立完成全程。",
        "打个不太恰当的比方，这有点像奥运会选手和青运会选手参加了同一场比赛身体条件和能力基础不一样，评价标准自然也要重新定义。",
        "为此，我们设定了一个“ 0.8系数” ：",
        "操控机器人要比自主机器人快20% , 才能获得相同分数。",
        "设定这个规则的初衷是鼓励发展机器人的“ 自主能力” 。",
        "虽然目前自主机器人的表现还不如操控机器人，但后者的上限很明显它的速度取决于操控员的速度。",
        "只要操控员和机器人之间的距离稍微拉开一点，机器人就容易跑偏，甚至摔倒。",
        "有人打趣说：",
        "“ 要是操控这些机器人的是｀飞人＇博尔特，或许真能破纪录。",
        "＂搏击项目进一步印证了这种关系。",
        "那场比赛中，我们邀请了八支高校队，还有女排国手薛阴她操控的宇树机器人成绩出色，最终夺冠。",
        "薛阴的反应速度、空间判断和节奏控制，让机器人在场上显得格外灵活。",
        "这些例子都说明，优秀的操控员确实能放大机器人的潜能，但这种模式终究只是过渡。",
        "随着算法、感知与传感技术的进步，机器人将越来越少依赖人类实时发出的指令。",
        "所以下——届，我们计划将“ 自406当机器人迎来它的奥运时刻主组” 和“操控组” 分开，让观众更直观地看到它们在一年之内的进化。",
        ":六· 运动会教会我们的事前面讲的是比赛中的种种细节。",
        "而对于赛场上的机器人运动员，以及他们背后的机构和公司来说，这场运动会又意昧着什么？",
        "在赛后采访中，我们听到了两个高频出现的答案：",
        "第一，很多问题被真正暴露出来了；",
