        "在机器人学习的世界里，几乎所有事情都是从仿真开始的。",
        "所谓仿真，就是先在虚拟世界“ 练＂，再到现实世界“干＂。",
        "工程师可以同时运行成百上千个虚拟场景让机器人在不同的“平行世界“ 反复练习，快速累积经验。",
        "这些虚拟环境，是严格遵循物理规律的“ 数字物理世界”。",
