        "机器人在虚拟世界里每一次弯膝、起跳、落地，背后都有物理求解器( physics solver ) 在计算转动力、摩擦力和冲击力，让仿真中的动作尽可能接近真实世界的动作。",
        "但问题在于，仿真终究是仿真，现实世界永远更复杂：",
