        "我们与安贞医院、福田汽车等机构合作，在“冰丝带“ 模拟了医院、酒店、工厂等真实的工作场景，让机器人在药物分拣、清洁服务、物料搬运等任务中竞技。",
        "参与场景赛物料整理项目的机器人因为我们越来越清楚地意识到，机器人终有一天会在这些地方成为人类的得力助手。",
        "它们需要做的不是进行惊艳的表演，而是踏408当机器人迎来它的奥运时刻实地完成一件件普通却重要的小事：",
