        "我们早已习惯在屏幕上看到那些会跳舞、会踢球的机器人，却常常忘了这些能力的意义从来不止于表演。",
        "机器人之所以要能跑、能跳、能保持平衡，是为了在未来的医院、酒店、工厂等场景中，更好地完成一项项具体的任务。",
        "所以，场景赛看起来可能不像是在“竞技＂，更像是在为未来排练为那个机器人能够与我们并肩工作、共同生活的未来提前彩抖［。",
        "沁· 1000天后的人形机器人运动会到这里，我们不妨把视线拉远，想象一下1000天后的人形机器人的世界。",
        "很多人觉得未来无法预测，但对我们来说，三年1000多天——是一个可以设想，也可以规划的时间尺度。",
