        "409你可能注意到了，在首届运动会中，场景赛的项目数量相比竞技赛还不算多。",
        "这是因为，目前许多生活场景对机器人作业来说还很困难。",
        "以机器人进入家庭、服务领域为例，有一个业内公认的“圣杯级难题”——让机器人理解并操控柔软的物体。",
        "这是因为，像被套、毛巾这样的东西在仿真环境中极难准确还原，它们既能弯曲、折叠，又具有一定的刚性和惯性，任何一个参数稍有偏差，机器人就可能“套不准” “对不齐＂，甚至连形状都无法识别。",
        "但近两年，我们已经看到突破的迹象。",
