        "这意昧着机器人不仅可以在虚拟环境中学会“握紧” 与“松开“ ，还在逐步掌握如何应对“非标准化” 的现实世界。",
        "所以我很乐观地相信，到举办第五届世界人形机器人运动会时，一些酒店或许已经由机器人承担整理布草的工作，部分家庭也开始让机器人协助完成日常家务。",
        "随着感知、力控、触觉反馈等关键问题被逐步攻克，机器人将真正跨过融入人类生活的“最后一公里”。",
        "在运动会上，我们也会对角逐场景赛的机器人提出更高的要求，让它们去挑战更复杂的任务。",
        "第二，我判断在那届运动会上，机器人会变得更强。",
        "你应该已经注意到，机器人的迭代速度和人类完全不在一个量级。",
        "人类运动员打破一项世界纪录，往往需要几年，甚至几十年；",
        "而在机器人运动员身上，进步几乎是按月，甚至按天计算的。",
        "410当机器人迎来它的奥运时刻不看未来，只看2025年从亦庄人形机器人半程马拉松时，20支队伍中只有6支完赛，完赛率不到30% , 到首届世界人形机器人运动会时，487场比赛几乎全部顺利完成，机器人从“ 不稳定地能跑” 到“ 系统性地能赛” ，这场质的飞跃，只用了短短100天。",
        "今后，机器人的进化速度只会更快。",
        "原因很简单：",
        "它们的学习方式正在发生结构性变化。",
        "前面提到，机器人进入真实世界前必须先在仿真世界中训练。",
        "但构建仿真世界中的仿真资产( simulation asset ) 很多时候是从零开始的设计结构、绘制模型、设置材质、标定参数. . . . . . 过程漫长，而且成本高昂，大大限制了机器人训练的速度。",
        "而现在的趋势是直接把现实世界中已有的数字设备比如CAI) 图纸、3D工程模型快速转化为“仿真就绪＂的资产。",
        "换句话说，我们不再“重造世界” ，而是让仿真系统理解世界。",
        "这意昧着仿真世界的构建速度，正逐渐追上物理世界的制造速度。",
        "有人预测过，未来，每一家制造企业在交付实体设备时，都可能同步交付它的“数字挛生体”汽车、家电、机械零件，都会拥有自己的数字版本。",
        "这些数字设备将被送入AI工厂，供机器人进行训练和优化。",
        "而当每一个真实物体都有对应的仿真版本时，机器人学习的仿真世界就几乎与现实世界无异。",
