        "谁的感知系统更精准，谁的决策算法更高效，谁的机械结构和控制系统在复杂环境下依然稳定可靠这些原本分散在实验室里的能力将被统一放进同一个“竞技坐标系” ，从而形成整个行业可比较、可验证、可迭代的标准。",
