        "这样的改变或许不会一夜之间发生，但终将重塑乡村的未来。",
        "当然，在城市里，你也会越来越常看到一些“ 长得不太一样”的建筑。",
        "小区门口的咖啡屋，线条简洁，仿佛从地面自然生长出来；",
        "公园里的书屋，圆顶镂空，光影斑驳；",
        "街角的公共卫生间，简洁明亮，又不乏巧思。",
        "这些一两层的小型建筑，面积不大，却充满创意和巧妙的空间表达。",
        "用传统工法做这种项目，成本高，周期长；",
        "而用3D打印，几天就能完成，成本只有传统方式的一半。",
        "更重要的是，它能实现传统施工难以做到的有机曲线过去打造一个弧形墙面，需要复杂模板与反复浇筑；",
        "而3D打印只需调整程序，就能“ 画” 出理想的形态。",
        "并且未来在一些度假区，你可能住进一栋由3D打印建成的两层民宿：",
        "外墙带着自然肌理，屋顶起伏如浪，与山景融为一体。",
        "景区中，那些形似贝壳、树枝或山石的艺术装置，也可能出自3D打印机器人之手。",
        "3D打印编织纹理的墙面466当3D打印建筑走进农村许多度假项目往往建在山间或海边，所处地区环境复杂、交通不便，项目又需要体现独特的设计感。",
        "传统施工要运送大量材料、设备和工人进场，而3D打印只需将机器运到现场，材料可就地取材，人力投入减少，建设效率却显著提升。",
        "不过，城市和度假区的3D打印建筑，更多的是一种美学上的探索——让城市更有趣，让建筑更自由。",
        "我认为，真正能带来结构性改变的，仍然是农村。",
        "建房更容易，维护更便捷，大量村庄的面貌也将在未来1000天里慢慢更新。",
        "新的协作方式前面我们提到，3D打印建筑有很多优势：",
        "成本低，速度快，还能实现传统工法难以完成的复杂形态。",
        "但随着实践的深入，我们越来越清楚地认识到，它更深层的价值不在于“建得更快” 或“ 更便宜” ,而在于它带来了一种全新的建造方式，一种正在重塑整个建筑行业生产关系的方式。",
        "3D打印建筑有一个显著特征：",
        "必须在虚拟世界先把房子建一遍。",
        "因为打印依赖的不是图纸，而是可以直接驱动机器的高精度二维模型。",
        "这个模型里，设计的每一根管线、每一个构件、每一个节点的连接方式，都必须在施工前被清晰定义。",
        "这意昧着，参与项目的所有专业人员都要在前期协同，把问题想透。",
        "建筑师在做设计，结构工程师能实时看到，发现问题立即反馈。",
        "467建筑师调整方案，结构工程师重新计算，水暖电工程师同步修改管线。",
        "所有的变化都在电脑中完成。",
        "相比之下，传统建筑方式虽然也会使用数字建模工具，但这些工具通常服务千设计阶段，和施工环节之间存在明显断层。",
        "施工图完成后，项目往往就直接进入现场实施，模型在施工阶段并不会持续更新或被严格执行。",
