        "在这篇文章中，我们重点解决一个问题：",
        "1000天后，在人工智能产业中，我国的哪些城市会脱颖而出？",
        "而这个问题涉及一个更本质的思考：",
        "一座城市产业崛起的关键因素是什么？",
        "如果把城市之间的产业竞逐想象成一场马拉松，那么前五公里的胜负，主要取决于起跑的位置和奔跑的速度。",
        "对应到城市竞争，这两个关键因素分别代表产业当下的发展水平和未来的发展动力。",
        "但这两个因素都很难直接测量，所以我们需要找到能够反映它们的代理指标，同样可以分成两部分。",
        "一是体现当下发展水平的产业规模、企业规模和人才规模。",
        "它们构成了城市的“ 起跑线” ，这些数据越高，说明城市的发展起点越高，越有可能占得先机。",
