        "一是人工智能核心产业规模，算的是直接支撑人工智能发展的部分，比如AI芯片、基础算法、核心软件平台等；",
        "二是人工智能产业规模，在核心产业基础上，还要加上人工智能在金融、制造、零售等行业创造的产业价值。",
