        "美国制造业在GDP中的占比如今只有约10% , 却贡献了约60％的科技创新。",
        "换句话说，好莱坞电影再卖座，金融体系再发达，批量生产再多的富人，服务业对科技的推动作用也比制造业小很多。",
        "这个逻辑应该是很好理解的，毕竟，管理一家对冲基金、运营一家五星级酒店并不需要太多物理、化学和基础研发方面的持续突破，而大规模、高精度的制造则离不开这些底层技术的迭代。",
        "因此，在芯片风波之后，中国在一个判断上形成了更清晰的认识：",
