        "一个直接原因是教培行业“ 批量制造焦虑＂，让中产阶级在“鸡娃内卷式” 的教育上投入太多。",
        "但是，从大专、本科到硕士、博士，这——路升级的供给与当下的产业需求之间其实存在巨大的脱节。",
        "教育改革因此变得迫在眉睫。",
        "493此前，国家在多份文件中强调，在高中阶段要保持普通高中与中等职业学校招生比例大体相当，便是鼓励更多孩子优先去学一门扎实的手艺，走上技工的职业发展道路。",
        "与此同时，高校和学科结构也经历了一轮“ 大洗牌” 。",
        "自2019年起，国家陆续推动几十所高职院校升格为大学，类型上仍属于职业教育，但授予学生本科学历，希望用这种方式打破民间对“职校出身” 的个体的偏见，让技能型人才的形象像德国的技工一样，有良好的社会美誉度。",
        "曾经被称为专科“ 小清华” 的深圳职业技术学院改名为深圳职业技术大学后，近年来本科投档线已经逼近甚至反超广东外语外贸大学、汕头大学、华南农业大学等老牌一本院校。",
        "它的升级，不只是“ 为深圳培养出更多的高级技工” 这么简单，更像是一个信号：",
        "中国版的德国双元制教育1正在加速成形。",
        "2024年，全国高校新增1839个专业点，停招或撤销的专业点超过3600个。",
        "新设专业中工科占比最高，被撤销的则多是偏文科方向的专业。",
        "还有，宁波东方理工大学、大湾区大学、福建福耀科技大学、深圳理工大学等——批新型研究型大学相继亮相，其投档线逼近甚至在部分地区反超一些老牌985高校。",
        "所有这些调整，指向的是同一件事：",
        "我们希望对标德国教育模式，重构学科和院校体系，向制造业和硬科技领域持续输送技能型人才。",
        "1 . 是指学生一边在职业学校学习理论课程，一边在企业接受带薪培训，由“学校＋企业“ 共同承担培养责任。",
        "这样培养出来的技术工人既有系统的知识体系，又有一线实践经验，在德国社会中具有较高的收入水平和职业地位。",
        "494半只脚跨入工业科技大国行列第二个大动作，是治理互联网、金融行业，在产业结构上推动从虚拟经济走向实体经济。",
        "这两个行业在过去十年乘着时代的电梯，坐收“超级地租＂，同时吸引了清华、北大等顶尖高校的大量毕业生。",
        "而近几年，我国通过新型举国体制，引导更多资源流向工业体系。",
