        "这一点与德国的路线有相似之处。",
        "我们可以先将德国和美国做一个对比。",
        "美国是典型的“服务业立国＂，它是全球服务贸易第一大国，互联网和金融行业高度发达，顶级富豪人数位居全球第一，但同时贫富差距也非常明显，有几千万人长期依靠政府发放的食物券生活。",
