        "由千制造业来钱没有金融、互联网行业那么快，德国10亿美元身家的企业家数量甚至少于印度；",
        "但高端制造业有一个好处是，它能让一线技工和产业工人分享到相当一部分附加值在德国，有些行业的高级技工收入跟高校教师差不多，普通家庭可以凭借稳定的工薪收入实现安居乐业，工业体系在这里发挥了“压舱石” 的作用。",
