        "AI推理的原理，是通过强化学习让AI学会用思维链来进行逻辑思考。",
        "而我们正在进入的第四阶段是Researcher的年代，也就是AI不仅可以推理，还能成为科学家的年代。",
        "在继续往下讲之前，我们需要先了解—— 些基础概念。",
        "我选择从大语言模型开始介绍它的工作机制是怎样的？",
        "前面提过，大语言模型的基本架构叫作Transfarmer ,它有三个核心概念：",
        "tokenize , embedding和attention。",
        "tokenize就是把人类的语言文本翻译成机器可以处理的基本单元，这个单元叫作token。",
        "有时候一个词可以对应一个token , 有时候一个词可能对应多个token ,比如indivisible这个词就对应两个token。",
        "这种对应关系是机器根据大数据算出来的，不一定直接对应语法上的词根关系。",
        "embedding就是把这些token用向量表示出来。",
        "这个过程就好像给AI铺开了一张多维的立体地图，在这幅地图上面，token和token之间的距离是可以用数学关系表达的。",
        "比如，few这个词跟little之间的距离可能比较近，而跟love之间的距离可能比较远；",
        "再559比如，man和woman之间的距离，可能跟king和queen之间的距离类似。",
        "大语言模型就是用这种方法理解词和词之间的意义关系的。",
        "它跟你对话的过程，就是根据这种意义关系正确预测它要生成的下一个token的过程。",
        "attention就是让模型动态地关注你跟它说的话，为你说话的内容分配不同的权重，从而正确理解上下文关系。",
        "这样，它生成的下一个token就可以回应你的对话内容。",
        "这三个过程环环相扣，让AI看起来懂得了我们的语言。",
        "而如果我们相信人类的智能最终是可以通过语言这一载体表达出来的，那么，当机器能够正确理解语言时，也就意昧着它在某种意义上拥有了类似千人的智能。",
        "这就是2017年以来Transfarmer取得的主要成就。",
        "从大概2023年开始，我们进入了AI推理的新阶段。",
        "AI不仅可以跟我们对话，还可以进行逻辑推理，推导出我们可能没有思考过的新理论和新观点。",
        "这种能力的实现，跟思维链和强化学习有关。",
        "什么是思维链？",
        "它其实是将逻辑思考展开为——环扣——环的链条的过程。",
        "比如你做数学题，要按步骤来解题，这个解题的过程就是思维链；",
        "再比如你读一本哲学书，遇到一个论证过程，你要层层理解哲学家是怎么论述的，这个过程也是思维链。",
        "那么，用强化学习让AI使用思维链进行思考是怎么回事？",
        "前面介绍过，强化学习不需要人的监督，它只是需要人给它正确的奖励信号。",
        "有了这个信号之后，AI就会像孩子反复检查自己数学题的步骤560我们正在进入AI成为科学家的时代有没有做错那样审视自己的思维链。",
        "经过这样的训练，AI就不仅可以预测下一个token , 还可以进行推理。",
        "最后，在2025年，我们正式进入了叫作Researcher的最新阶段。",
        "AI不仅可以检查自己解题的步骤，还可以像科学家一样研究了。",
        "Researcher与上一个叫作Reasoner的阶段有什么不同？",
        "第—— , Researcher的复杂程度要高很多。",
        "就像做科研比做数学题的复杂程度要高很多一样。",
        "这主要是因为，我们今天对GPU的利用效率大大提高了。",
        "在Reasoner年代，模型一次只能处理一个问题；",
        "而在Researcher年代，模型可以并行处理多个问题，并根据任务类型自主分配算力资源。",
