        "第二，Researcher可以理解任务的性质，并且知道该使用什么样的工具来完成任务。",
        "很多人觉得，大模型并不是真的拥有智能，因为大模型有幻觉，所以它计算加减乘除也会出错。",
        "其实这是对智能的错误理解。",
        "小学生学习加减乘除要反复练习，但是高中生还需要练习吗？",
        "不需要了，高中生可以直接用计算器。",
        "而对科学家来说，他们其实有更多的工具来处理这些任务。",
        "关键不在于能不能算对加减乘除，关键在于你要知道什么时候用什么工具处理什么任务。",
