exports.main = async (event, context) => {
  const { action, chId } = event;

  if (action === 'index') {
    return { success: true, data: INDEX_DATA };
  }

  if (action === 'chapter') {
    const chapter = CHAPTER_SUMMARIES[chId];
    if (!chapter) {
      return { success: false, error: `Chapter ${chId} not found` };
    }
    return { success: true, data: chapter };
  }

  return { success: false, error: 'Unknown action' };
};

